#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, datetime as dt, importlib.util, os, py_compile, shutil, subprocess, sys
from pathlib import Path

VERSION="0.10.1"
MODIFIED_B64={'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/runtime.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64={'backend/tests/vision_app/test_vision_app_v1010.py': '', 'frontend/docs/llm_context/updates/v1010_computer_vision_debug_source_hotfix.md': ''}
MODIFIED={k:{"old":base64.b64decode(v["old"]).decode("utf-8"),"new":base64.b64decode(v["new"]).decode("utf-8")} for k,v in MODIFIED_B64.items()}
CREATED={k:base64.b64decode(v).decode("utf-8") for k,v in CREATED_B64.items()}

def roots(f=None,b=None):
    c=Path.cwd().resolve(); fs=[]; bs=[]
    if f: fs.append(Path(f).expanduser().resolve())
    if b: bs.append(Path(b).expanduser().resolve())
    fs += [c,c/"LambdaVisionSuper",c.parent/"LambdaVisionSuper"]
    bs += [c,c/"LambdaVisionSuperBackEnd",c.parent/"LambdaVisionSuperBackEnd"]
    fe=next((p for p in fs if (p/"src/Pages/ComputerVisionPage.tsx").exists()),None)
    be=next((p for p in bs if (p/"app/services/vision_app/runtime.py").exists()),None)
    if not fe: raise RuntimeError("Cannot locate LambdaVisionSuper frontend. Use --frontend /path/to/LambdaVisionSuper")
    if not be: raise RuntimeError("Cannot locate LambdaVisionSuperBackEnd. Use --backend /path/to/LambdaVisionSuperBackEnd")
    return fe,be

def path(fe,be,v):
    return (fe/v[len("frontend/"):]) if v.startswith("frontend/") else (be/v[len("backend/"):])

def mstate(p,o,n):
    if not p.exists(): return "MISSING"
    s=p.read_text(encoding="utf-8")
    return "OK" if s==n else "UPDATE" if s==o else "CONFLICT"

def cstate(p,n):
    if not p.exists(): return "CREATE"
    return "OK" if p.read_text(encoding="utf-8")==n else "CONFLICT"

def scan(fe,be):
    print("="*104)
    print("COMPUTER VISION V0.10.1 — DEBUG SOURCE HOTFIX")
    print("="*104)
    print("Frontend :",fe); print("Backend  :",be); print()
    bad=0
    for v,x in MODIFIED.items():
        s=mstate(path(fe,be,v),x["old"],x["new"]); print(f"  [{s:12}] {v}")
        bad += s in ("MISSING","CONFLICT")
    for v,n in CREATED.items():
        s=cstate(path(fe,be,v),n); print(f"  [{s:12}] {v}")
        bad += s=="CONFLICT"
    print()
    print("v0.10.1 contract:")
    print("  Global Debug input = full preview image")
    print("  ROI Debug input = located ROI crop after Global Filter/locator")
    print("  No test/camera image -> scope preview falls back to persisted Master Sample")
    print("  Global explicit test-image preview does not require a Master Sample")
    print("  Debug image artifacts remain lazy-loaded")
    print("  LLM handoff note + context regeneration included")
    if bad: print(f"[WARN] {bad} conflict/base issue(s); apply will stop safely.")
    return 0

def pre(fe,be):
    e=[]
    for v,x in MODIFIED.items():
        s=mstate(path(fe,be,v),x["old"],x["new"])
        if s not in ("UPDATE","OK"): e.append(f"{v}: {s}")
    for v,n in CREATED.items():
        s=cstate(path(fe,be,v),n)
        if s not in ("CREATE","OK"): e.append(f"{v}: {s}")
    if e: raise RuntimeError("Safe update stopped:\n  - "+"\n  - ".join(e))

def regen(fe,be):
    g=fe/"tools/generate_llm_context_map.py"
    if not g.exists():
        print("[SKIP] Context generator not found"); return
    cmd=[sys.executable,str(g),"--frontend",str(fe),"--backend",str(be)]
    if "--output-dir" in g.read_text(encoding="utf-8"):
        cmd += ["--output-dir",str(fe/"docs/llm_context")]
    p=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
    if p.returncode:
        raise RuntimeError("Context generation failed:\n"+p.stdout+"\n"+p.stderr)
    if p.stdout.strip(): print(p.stdout.strip())

def apply(fe,be):
    pre(fe,be)
    stamp=dt.datetime.now().strftime("%Y%m%d_%H%M%S")
    bak=fe/".lambda_updater_backups"/f"computer_vision_v1010_{stamp}"
    bak.mkdir(parents=True,exist_ok=True)
    for v in list(MODIFIED)+list(CREATED):
        p=path(fe,be,v)
        if p.exists():
            q=bak/v; q.parent.mkdir(parents=True,exist_ok=True); shutil.copy2(p,q)
    for v,x in MODIFIED.items():
        p=path(fe,be,v)
        if p.read_text(encoding="utf-8")!=x["new"]:
            p.write_text(x["new"],encoding="utf-8"); print("[WRITE]",v)
    for v,n in CREATED.items():
        p=path(fe,be,v); p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists() or p.read_text(encoding="utf-8")!=n:
            p.write_text(n,encoding="utf-8"); print("[WRITE]",v)
    print("[INFO] Regenerating LLM context docs...")
    regen(fe,be)
    print("[OK] Backup:",bak)
    print("Run verify next.")
    return 0

def ts_transpile(fe):
    files=[
        path(fe,Path("/unused"),v)
        for v in list(MODIFIED)+list(CREATED)
        if v.startswith("frontend/") and v.endswith((".ts",".tsx"))
    ]
    code=r"""
const fs=require("fs");
const ts=require("typescript");
let bad=false;
for(const file of process.argv.slice(1)){
 const src=fs.readFileSync(file,"utf8");
 const r=ts.transpileModule(src,{fileName:file,reportDiagnostics:true,compilerOptions:{
  jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext
 }});
 const errs=(r.diagnostics||[]).filter(d=>d.category===ts.DiagnosticCategory.Error);
 if(errs.length){bad=true;console.error("TS_ERROR",file);for(const e of errs)console.error(ts.flattenDiagnosticMessageText(e.messageText,"\n"));}
}
process.exit(bad?1:0);
"""
    env=dict(os.environ)
    root=subprocess.run(["npm","root","-g"],text=True,capture_output=True)
    if root.returncode==0 and root.stdout.strip():
        env["NODE_PATH"]=root.stdout.strip()+(os.pathsep+env["NODE_PATH"] if env.get("NODE_PATH") else "")
    return subprocess.run(["node","-e",code,*map(str,files)],cwd=str(fe),env=env,text=True,capture_output=True)

def verify(fe,be,skip_build=False):
    print("="*104)
    print("VERIFY COMPUTER VISION V0.10.1")
    print("="*104)
    fail=0
    checks=[
      ("ROI preview stores crop only after ROI location",
       'preview_input = _crop_array(filtered_test, found.rect)' in (be/"app/services/vision_app/runtime.py").read_text()
       and 'label=f"{found.name} · Input"' in (be/"app/services/vision_app/runtime.py").read_text()),
      ("Global preview stores full input",
       'label="Global · Input"' in (be/"app/services/vision_app/runtime.py").read_text()),
      ("Scope preview supports Master fallback",
       '_decode_or_master' in (be/"app/api/v1/endpoints/vision_app_api.py").read_text()
       and '"preview_source": preview_source' in (be/"app/api/v1/endpoints/vision_app_api.py").read_text()),
      ("Global explicit image preview does not require Master",
       'master = preview_image if scope_id == "global" else repository.load_master(program_id)' in (be/"app/api/v1/endpoints/vision_app_api.py").read_text()),
      ("Frontend no longer refuses missing test image",
       "Choose/capture a test image before debugging a Filter stack" not in (fe/"src/Pages/ComputerVisionPage.tsx").read_text()),
      ("Frontend labels Master fallback",
       "Master fallback" in (fe/"src/Pages/ComputerVisionPage.tsx").read_text()),
      ("API preview accepts optional image",
       "file?:Blob|null" in (fe/"src/api/visionAppApi.ts").read_text()),
      ("ROI debug regression test installed",
       (be/"tests/vision_app/test_vision_app_v1010.py").exists()),
      ("v0.10.1 handoff MD",
       (fe/"docs/llm_context/updates/v1010_computer_vision_debug_source_hotfix.md").exists()),
      ("Context generator v0.10.1",
       "v0.10.1 Computer Vision" in (fe/"tools/generate_llm_context_map.py").read_text()),
    ]
    for label,ok in checks:
        print(f"[{'OK' if ok else 'FAIL'}] {label}"); fail += 0 if ok else 1

    pyfiles=[path(fe,be,v) for v in list(MODIFIED)+list(CREATED) if v.startswith("backend/") and v.endswith(".py")]
    pybad=[]
    for p in pyfiles:
        try: py_compile.compile(str(p),doraise=True)
        except Exception as e: pybad.append(f"{p.relative_to(be)}: {e}")
    if pybad:
        print("[FAIL] Python syntax"); [print("  -",x) for x in pybad]; fail+=len(pybad)
    else:
        print(f"[OK] Python syntax ({len(pyfiles)} changed/new backend files)")

    if importlib.util.find_spec("pytest") is not None and (be/"tests/vision_app").exists():
        proc=subprocess.run([sys.executable,"-m","pytest","-q","tests/vision_app"],cwd=str(be),text=True,capture_output=True)
        if proc.returncode==0:
            print("[OK] Vision App regression tests")
            if proc.stdout.strip(): print(proc.stdout.strip())
        else:
            print("[FAIL] Vision App regression tests")
            print((proc.stdout+"\n"+proc.stderr).strip()); fail+=1
    else:
        print("[SKIP] pytest / Vision App tests unavailable")

    ts=ts_transpile(fe); msg=(ts.stdout+"\n"+ts.stderr).strip()
    if ts.returncode==0: print("[OK] TypeScript syntax/transpile")
    elif "Cannot find module 'typescript'" in msg or "MODULE_NOT_FOUND" in msg: print("[SKIP] TypeScript module unavailable")
    else: print("[FAIL] TypeScript syntax/transpile"); print(msg); fail+=1

    if not skip_build and (fe/"package.json").exists() and (fe/"node_modules").exists():
        proc=subprocess.run(["npm","run","build"],cwd=str(fe))
        if proc.returncode==0: print("[OK] Frontend npm build")
        else: print("[FAIL] Frontend npm build"); fail+=1
    else: print("[SKIP] Frontend npm build")

    try:
        regen(fe,be)
        arch=fe/"docs/llm_context/SYSTEM_ARCHITECTURE.md"
        if arch.exists():
            print("[OK] Regenerated LLM context docs")
        else:
            print("[FAIL] Regenerated LLM context docs"); fail+=1
    except Exception as e:
        print("[FAIL] Context regeneration:",e); fail+=1

    if fail:
        print(f"[FAIL] v0.10.1 verification finished with {fail} issue(s).")
        return 1
    print("[OK] Computer Vision v0.10.1 debug-source hotfix verified.")
    return 0

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("command",choices=["scan","apply","verify"])
    ap.add_argument("--frontend"); ap.add_argument("--backend"); ap.add_argument("--skip-build",action="store_true")
    a=ap.parse_args()
    try:
        fe,be=roots(a.frontend,a.backend)
        if a.command=="scan": return scan(fe,be)
        if a.command=="apply": return apply(fe,be)
        return verify(fe,be,a.skip_build)
    except Exception as e:
        print("[ERROR]",e); return 2
if __name__=="__main__": raise SystemExit(main())
